#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 1 delivery: samplers
#   rtl/sampler_ntt_k.vhd  S1 SampleNTT        FIPS 203 Alg 7
#   rtl/sampler_misc.vhd   S2 SamplePolyCBD    FIPS 203 Alg 8   (eta=2)
#                          S3 RejNTTPoly       FIPS 204 Alg 30
#                          S4 RejBoundedPoly   FIPS 204 Alg 31  (eta=4)
#                          S5 SampleInBall     FIPS 204 Alg 29  (tau=49)
#                          S6 ExpandMask       FIPS 204 Alg 34  (gamma1=2^19)
#   verif/tb_sampler.vhd   integration testbench: real keccak_sponge drives
#                          all six samplers through incremental squeeze
#   verif/mutate_samp.sh   10 mutations, all must be killed (run separately)
#
# Requires the Layer 1 Keccak and NTT deliveries to be installed already
# (rtl/keccak_*.vhd and rtl/ntt_tables_pkg.vhd).
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected single output line:
# PQC L1 SAMPLER PASS vectors=39 sig=af3eec119dd0b860
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif"
  for f in rtl/keccak_pkg.vhd rtl/keccak_f1600.vhd rtl/keccak_sponge.vhd \
           rtl/ntt_tables_pkg.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f (run the Keccak and NTT deliveries first)"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/sampler_ntt_k.vhd" << 'B64EOF'
